    margin: '10px 0 0 0', 
    fontSize: '2.1rem', 
    fontWeight: 800 
  },

  mainGrid: { 
    display: 'grid', 
    gridTemplateColumns: '2fr 1fr', 
    gap: '28px', 
    marginBottom: '40px' 
  },

  section: { 
    backgroundColor: COLORS.surface, 
    borderRadius: '18px', 
    padding: '32px', 
    boxShadow: '0 10px 30px rgba(0,0,0,0.07)', 
    border: `1px solid ${COLORS.border}` 
  },

  sectionTitle: { 
    margin: '0 0 24px 0', 
    fontSize: '1.25rem', 
    fontWeight: 700, 
    color: COLORS.textMain 
  },

  table: { 
    width: '100%' 
  },

  tableHeader: { 
    display: 'flex', 
    padding: '14px 0', 
    borderBottom: `2px solid ${COLORS.border}`, 
